function fresh(){return{gems:0,trophies:[],unlocks:['Warrior','Paladin','Rogue','Ranger','Mage','Priest'],gearTierUnlocked:1,history:[],training:{},run:null}}
function load(){try{const saved=JSON.parse(localStorage.getItem(SAVE_KEY)||'null')||{};if(saved.gems==null)saved.gems=saved.treasury||0;(saved.run?.perks||[]).forEach(p=>{if(p.name==='Field Medicine'){p.desc='Party heals 4% after each battle';p.value=.04}});return Object.assign(fresh(),saved)}catch{return fresh()}}
function save(){localStorage.setItem(SAVE_KEY,JSON.stringify(state))}
function toast(msg){const e=document.createElement('div');e.className='toast';e.textContent=msg;$('#toast').append(e);setTimeout(()=>e.remove(),2600)}
function trainingRank(k){return state.training?.[k]||0}
function runBoonTotal(type){return state.run?.perks?.filter(p=>p.type===type).reduce((total,p)=>total+(Number(p.value)||0),0)||0}
function diminishingAttributeBonus(attribute,linearAt100,logarithmicGain){const value=Math.max(0,attribute||0);return value<=100?value*(linearAt100/100):linearAt100+logarithmicGain*Math.log(1+(value-100)/100)}
function strengthHpBonus(str){return Math.floor(diminishingAttributeBonus(str,25,10))}
function traitStats(h){return CHARACTER_TRAIT_STATS[h?.trait]||CHARACTER_TRAIT_STATS.Balanced}
function characterCoreStat(h,key,includeGear=true){const base=CHARACTER_BASE[h.class]||{},growth=CLASS_LEVEL_GROWTH[h.class]||{},trait=traitStats(h),gear=includeGear?gearStats(h):{},race=RACE_DATA[h.race]||{},levels=Math.max(0,(h.level||1)-1),raw=(base[key]||0)+levels*(growth[key]||0)+(trait[key]||0)+(gear[key]||0);return Math.round(raw*(CHARACTER_RARITY_MULTIPLIER[h.rarity]||1)*(race.mult?.[key]||1))}
function naturalMaxHp(h,includeGear=true){const growth=CLASS_LEVEL_GROWTH[h.class]||{},trait=traitStats(h),gear=includeGear?gearStats(h):{},levels=Math.max(0,(h.level||1)-1),rarity=CHARACTER_RARITY_MULTIPLIER[h.rarity]||1,raceHp=RACE_DATA[h.race]?.mult?.hp||1,raw=CLASSES[h.class].hp+3+levels*(growth.hp||0)+(trait.hp||0)+(gear.hp||0),withStrength=Math.round(raw*rarity)+strengthHpBonus(characterCoreStat(h,'str',includeGear));return Math.max(1,Math.round(withStrength*(trait.hpMult||1)*raceHp*(1+trainingRank('hp')*.04)))}
function legacyNaturalMaxHp(h){return Math.round((LEGACY_CLASS_HP[h.class]||CLASSES[h.class].hp)*(1+Math.max(0,(h.level||1)-1)*.13)*(1+trainingRank('hp')*.04)*(RACE_DATA[h.race]?.mult?.hp||1))}
function rollCharacterRarity(){const rank=state.training?.recruitLuck||0,r=Math.random(),mythic=rank*.0005,legendary=.0015+rank*.002,epic=.008+rank*.006,rare=.035+rank*.015,uncommon=.16+rank*.025;if(r<mythic)return'Mythic';if(r<mythic+legendary)return'Legendary';if(r<mythic+legendary+epic)return'Epic';if(r<mythic+legendary+epic+rare)return'Rare';if(r<mythic+legendary+epic+rare+uncommon)return'Uncommon';return'Common'}
function makeHero(level=1,forcedClass=null){const cls=forcedClass||pick(state.unlocks),base=CLASSES[cls],ability=ABILITIES[cls],races=Object.keys(RACE_DATA),race=pick(races)||'Human',raceDef=RACE_DATA[race]||{},mult=raceDef.mult||{},hero={id:uid(),name:pick(NAMES),class:cls,race,rarity:rollCharacterRarity(),trait:pick(CHARACTER_TRAITS),subclass:null,level,xp:0,maxHp:1,hp:1,maxMana:Math.round((ability.maxMana+trainingRank('mana')*5)*(mult.mana||1)),mana:0,manaRegen:ability.regen+trainingRank('manaRegen')*.2,manaRegenVersion:3,abilityCooldown:0,atk:Math.round(base.atk*(1+(level-1)*.11)*(1+(raceDef.flat?.attackMult||0))),speed:base.speed*(1+trainingRank('attackSpeed')*.02),raceAppliedVersion:1,hpFormulaVersion:2,crit:.05+trainingRank('critChance')*.015,gear:{Weapon:{name:'Guild-Issue '+cls+' Weapon',slot:'Weapon',rarity:'Common',tier:1,weaponPower:5,weaponTemplate:Object.keys(ITEM_DATA.weapons).find(n=>n.toLowerCase().replace(/ /g,'')===base.weapon.replace('.png','').replace('-',''))||null,image:`images/items/weapons/${base.weapon}`},Armor:null,Accessory:null},kills:0,damage:0};hero.maxHp=naturalMaxHp(hero);hero.hp=hero.maxHp;hero.mana=hero.maxMana;return hero}
function classRoster(level,copies=1){return state.unlocks.flatMap(cls=>Array.from({length:copies},()=>makeHero(level,cls)))}
function ensureHeroResources(h){const a=ABILITIES[h.class];h.race=h.race||'Human';h.rarity=h.rarity||'Common';h.trait=h.trait||'Balanced';h.subclass=h.subclass??null;h.augments=Array.isArray(h.augments)?h.augments:[];h.damage=Number(h.damage)||0;h.damageTaken=Number(h.damageTaken)||0;h.healing=Number(h.healing)||0;if(!h.raceAppliedVersion){const mult=RACE_DATA[h.race]?.mult||{},hpRatio=h.hp/h.maxHp,manaRatio=h.mana/h.maxMana;h.maxHp=Math.round(h.maxHp*(mult.hp||1));h.hp=h.maxHp*hpRatio;h.maxMana=Math.round((h.maxMana||a.maxMana)*(mult.mana||1));h.mana=h.maxMana*(Number.isFinite(manaRatio)?manaRatio:1);h.raceAppliedVersion=1}if(h.hpFormulaVersion!==2&&Object.keys(RACE_DATA).length){const ratio=h.maxHp?h.hp/h.maxHp:1,delta=naturalMaxHp(h)-legacyNaturalMaxHp(h);h.maxHp=Math.max(1,Math.round(h.maxHp+delta));h.hp=Math.max(h.hp>0?1:0,Math.min(h.maxHp,h.maxHp*ratio));h.hpFormulaVersion=2}if(h.attackSpeedVersion!==2){h.speed*=h.slowAttackMigration?.35/.65:.35;h.slowAttackMigration=true;h.attackSpeedVersion=2}h.maxMana=h.maxMana||a.maxMana;h.mana=Math.min(h.maxMana,h.mana??h.maxMana);if(h.manaRegenVersion!==3){h.manaRegen=a.regen+trainingRank('manaRegen')*.2;h.manaRegenVersion=3}h.manaRegen=h.manaRegen||a.regen;h.abilityCooldown=Math.max(0,h.abilityCooldown||0);return h}
function beginDraft(){draftSelection=[null,null];state.draftSlots=[classRoster(1),classRoster(1)];save();renderDraft()}
function openDraftSlot(slot){const candidates=state.draftSlots?.[slot]||classRoster(1);showOverlay(`Choose Party Slot ${slot+1}`,`<p class="muted">Choose one candidate from any class. You may use the same class in both slots.</p><div class="draftClassGrid">${candidates.map(h=>`<div class="draftCandidate">${heroCard(h)}<button class="btn gold" onclick="chooseDraftHero(${slot},${h.id})">Choose ${h.class}</button></div>`).join('')}</div>`)}
function chooseDraftHero(slot,id){draftSelection[slot]=id;closeOverlay();renderDraft()}
function startRun(){if(draftSelection.filter(Boolean).length!==2)return;const candidates=(state.draftSlots||[]).flat(),heroes=draftSelection.map(id=>candidates.find(h=>h.id===id)).filter(Boolean);state.run={id:uid(),started:Date.now(),region:0,step:0,encounters:0,gold:40,heroes,inventory:[],consumables:{},perks:[],relics:[],nodes:makeRegionMap(),mode:'map',pendingReward:null,battle:null,log:[]};delete state.draftSlots;save();render()}
function makeNodes(index=0){const step=index+1,relicRow=step===5||step===10,shrineRow=step===3||step===8,preBossRow=step===12,pool=['combat','event','treasure','merchant','elite'];for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}if(relicRow)return['relic'];if(shrineRow)return['shrine'];if(preBossRow)return['camp',...pool.slice(0,2)].sort(()=>Math.random()-.5);return pool.slice(0,3)}
function makeRegionMap(){return Array.from({length:12},(_,index)=>makeNodes(index))}
function normalizeRegionMap(r){const source=Array.isArray(r.nodes)&&r.nodes.length===12?r.nodes:makeRegionMap();r.nodes=source.map((row,index)=>{const step=index+1,relicRow=step===5||step===10,shrineRow=step===3||step===8,preBossRow=step===12,unique=new Set(row||[]),specials=(row||[]).filter(x=>x==='camp'||x==='relic'||x==='shrine'),valid=relicRow?row?.length===1&&row[0]==='relic':shrineRow?row?.length===1&&row[0]==='shrine':preBossRow?row?.length===3&&unique.size===3&&row.includes('camp')&&!row.includes('relic')&&!row.includes('shrine'):row?.length===3&&unique.size===3&&specials.length===0;return valid?row:makeNodes(index)});return r.nodes}
function img(path,cls='portrait'){return `<img class="${cls}" src="${ASSET}${path}" alt="">`}
function gearSlotVisual(h,slot,i){const it=h.gear[slot],fallback=['⚔','▣','◇'][i];return `<span class="gearSlot" onclick="event.stopPropagation();inspectGear(${h.id},'${slot}')">${it?`<span class="gearMiniArt"><img src="../guildmaster/${it.image||`images/items/${itemFolder(slot)}/${itemSlug(it.name)}.png`}" alt="" onerror="this.style.display='none';this.nextElementSibling.style.display='inline'"><i style="display:none">${fallback}</i></span>`:fallback}<span>${it?.name||'Empty '+slot}</span></span>`}
function heroCard(h){ensureHeroResources(h);const hp=clamp(h.hp/h.maxHp*100,0,100),base=CLASSES[h.class];return `<div class="hero ${h.hp<=0?'dead':''}" onclick="event.stopPropagation();inspectHero(${h.id})" role="button" tabindex="0" title="Inspect ${h.name}">${img('classes/'+base.icon)}<div><div class="name">${h.name}</div><div class="sub">${h.race} · ${h.class} · Lv. ${h.level} · <span class="rarity-${h.rarity}">${h.rarity}</span></div><div class="bar"><i style="width:${hp}%"></i></div><div class="stats"><span>${Math.max(0,Math.ceil(h.hp))}/${h.maxHp} HP</span><span>${effectiveAtk(h)} ATK</span></div></div><div class="gear">${['Weapon','Armor','Accessory'].map((slot,i)=>gearSlotVisual(h,slot,i)).join('')}</div><span class="inspectHint">Click character or gear to inspect</span></div>`}
function findHero(id){return state.run?.heroes.find(h=>h.id===id)||(state.draftSlots||[]).flat().find(h=>h.id===id)||(state.run?.recruitChoices||[]).find(h=>h.id===id)}
function heroSheetStats(h){const base=CHARACTER_BASE[h.class],gear=gearStats(h),race=RACE_DATA[h.race]||{},flat=race.flat||{};return{hp:h.maxHp,mana:h.maxMana,str:characterCoreStat(h,'str'),dex:characterCoreStat(h,'dex'),int:characterCoreStat(h,'int'),def:characterCoreStat(h,'def'),mdef:characterCoreStat(h,'mdef'),block:(base.block||0)+(gear.block||0)+(flat.block||0),threat:heroThreat(h),manaRegen:h.manaRegen+gear.manaRegen,initiative:heroInitiative(h),attackSpeed:h.speed*(1+gear.attackSpeed/100)*(1+runBoonTotal('speed')),crit:h.crit+gear.critChance+runBoonTotal('crit'),regen:gear.regen,physicalDodge:gear.physicalDodgeBonus+(flat.physicalDodge||0),magicalDodge:gear.magicalDodgeBonus+(flat.magicalDodge||0)}}
function inspectHero(id){
 const h=findHero(id);if(!h)return;
 const z=heroSheetStats(h),race=RACE_DATA[h.race]||{},sub=(SUBCLASS_DATA[h.class]||[]).find(x=>x.id===h.subclass),ability=ABILITIES[h.class],turnAbilities=TURN_ABILITIES[h.class],passive=CLASS_PASSIVES[h.class],augments=(h.augments||[]).map(id=>ABILITY_AUGMENTS[h.class].find(x=>x[0]===id)).filter(Boolean);
 showOverlay(h.name,`<div class="characterInspect"><div class="characterIdentity">${img('classes/'+CLASSES[h.class].icon)}<div><h3>${h.name}</h3><div class="muted">${sub?.name||h.class} · ${h.race} · Level ${h.level} · <span class="rarity-${h.rarity}">${h.rarity}</span></div><div class="muted">${h.trait}</div></div></div><div class="statSheet">${[['HP',z.hp],['Mana',z.mana],['Mana Regen',z.manaRegen],['Attack',effectiveAtk(h)],['Attack Speed',z.attackSpeed.toFixed(2)+'×'],['Threat',z.threat.toFixed(2)],['STR',z.str],['DEX',z.dex],['INT',z.int],['DEF',z.def],['MDEF',z.mdef],['Block',z.block],['Crit',(z.crit*100).toFixed(1)+'%'],['HP Regen',z.regen],['Physical Dodge',(z.physicalDodge*100).toFixed(1)+'%'],['Magic Dodge',(z.magicalDodge*100).toFixed(1)+'%']].map(([k,v])=>`<div class="sheetStat"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><section class="inspectSection abilityInspect"><h3>Ability · ${ability.name}</h3><p>${ABILITY_DESCRIPTIONS[h.class]}</p><div class="itemStats"><span>${abilityCost(h)} Mana</span><span>${abilityCooldown(h).toFixed(1)}s Cooldown</span></div>${augments.length?`<h4>Run Augments</h4>${augments.map(a=>`<p><b>${a[1]}</b><br><span class="muted">${a[2]}</span></p>`).join('')}`:''}</section><section class="inspectSection"><h3>Class Passive · ${passive[0]}</h3><p class="muted">${passive[1]}</p></section><section class="inspectSection"><h3>Race Passive · ${race.passive||'Heritage'}</h3><p class="muted">${race.desc||'No racial modifier.'}</p></section>${sub?`<section class="inspectSection"><h3>Subclass · ${sub.name}</h3><p><b>Passive</b><br>${sub.passive}</p><p class="muted"><b>Active</b><br>${sub.active}</p></section>`:''}<section class="inspectSection"><h3>Equipment</h3><div class="inspectLoadout">${['Weapon','Armor','Accessory'].map(slot=>{const it=h.gear[slot];return `<button class="gearInspectCard" onclick="closeOverlay();inspectGear(${h.id},'${slot}')"><span>${slot}</span><strong>${it?.name||'Empty'}</strong><small>${it?itemStatLines(it).join(' · '):'Nothing equipped'}</small></button>`}).join('')}</div></section></div><div class="actions"><button class="btn" onclick="closeOverlay()">Close</button></div>`)
}
function inspectGear(heroId,slot){const h=findHero(heroId),it=h?.gear?.[slot];if(!h)return;if(!it)return showOverlay('Empty '+slot,`<p class="muted">${h.name} has nothing equipped in this slot.</p><div class="actions"><button class="btn" onclick="closeOverlay();inspectHero(${h.id})">Back to character</button></div>`);showOverlay(it.name,`<div class="selectedItem">${itemArt(it)}<div><div class="name rarity-${it.rarity||'Common'}">${it.name}</div><div class="muted">Tier ${it.tier||1} · ${it.rarity||'Common'} ${slot}${it.armorClass?' · '+it.armorClass:''}</div><div class="itemStats">${itemStatLines(it).map(s=>`<span>${s}</span>`).join('')}</div></div></div><div class="inspectSection"><h3>Equipped by ${h.name}</h3><p class="muted">${it.damageType?`${it.damageType} damage · `:''}${it.weaponTemplate||it.armorClass||slot}</p></div><div class="actions"><button class="btn" onclick="closeOverlay();inspectHero(${h.id})">Back to character</button><button class="btn" onclick="closeOverlay()">Close</button></div>`)}
function header(){const r=state.run;return `<div class="topbar"><div class="title"><h1>Guildmaster: Dungeons</h1><p>${r?`${REGIONS[r.region]?.name||'Expedition Complete'} · ${r.heroes.length} adventurers · ${r.encounters} battles`:'Every expedition writes a new guild legend.'}</p></div><div class="resources"><span class="chip">Gems <b>${state.gems}◆</b></span>${r?`<button class="chip inventoryTab ${r.mode==='inventory'?'active':''}" onclick="openRunInventory()">Inventory <b>${(r.inventory||[]).length}</b></button><span class="chip">Run Gold <b>${r.gold}g</b></span><span class="chip">Region <b>${r.region+1}/4</b></span>`:`<span class="chip">Gear Tier <b>${state.gearTierUnlocked||1}</b></span><span class="chip">Victories <b>${state.history.filter(x=>x.won).length}</b></span>`}</div></div>`}
function render(){clearInterval(battleTimer);battleTimer=null;cancelAnimationFrame(battleFrame);battleFrame=null;$('#app').innerHTML=`<div class="shell">${header()}${state.run?renderRun():renderGuild()}</div>`;if(!state.run)renderRecruitmentFortune();if(state.run?.mode==='combat')startBattleLoop();if(state.run?.mode==='map')requestAnimationFrame(focusCurrentMapNode)}
function renderGuild(){return `<div class="grid"><section class="panel"><div class="screenTitle"><h2>The Guild Endures</h2><p class="muted">Every expedition strengthens those who follow. Gear tier ${state.gearTierUnlocked||1} unlocked.</p></div><div class="actions" style="justify-content:center"><button class="btn primary" onclick="beginDraft()">Recruit a New Expedition</button></div><h3 style="margin-top:25px">Permanent Training</h3><p class="muted">Training uses Gems earned by making progress through expeditions. Run Gold is only spent during a run.</p><div class="trainingGrid">${TRAINING.map(([k,n,label,gain,base])=>{const rank=state.training?.[k]||0,cost=base*(rank+1);return `<div class="upgrade trainingUpgrade"><div><b>${n} · ${rank}/10</b><div class="muted">${label} ${gain} per rank</div></div><button class="btn" ${rank>=10||state.gems<cost?'disabled':''} onclick="buyTraining('${k}',${cost})">${rank>=10?'Mastered':cost+'◆'}</button></div>`}).join('')}</div></section><aside class="panel"><h3>Hall of Heroes</h3><p class="muted">Victors retire. The fallen are remembered.</p><div class="hallList">${state.history.length?state.history.slice().reverse().map(x=>`<div class="history"><b>${x.won?'VICTORY':'FALLEN'} · ${x.party.join(', ')}</b><div class="muted">Reached ${x.region} · ${x.battles} battles · earned ${x.gems??0} Gems</div></div>`).join(''):'<div class="muted">No expeditions recorded yet.</div>'}</div><h3 style="margin-top:16px">Boss Trophies</h3><div class="muted">${state.trophies.length?state.trophies.join('<br>'):'No trophies recovered.'}</div></aside></div>`}
function buyTraining(k,cost){state.training=state.training||{};if(state.gems<cost||(state.training[k]||0)>=10)return;state.gems-=cost;state.training[k]=(state.training[k]||0)+1;save();render()}
function renderRecruitmentFortune(){const rank=state.training?.recruitLuck||0,cost=150*(rank+1),target=$('.trainingGrid');if(!target)return;target.insertAdjacentHTML('afterend',`<section class="fortuneUpgrade"><div><div class="eyebrow">RECRUITMENT UPGRADE</div><h3>Fortune-Touched Applicants · ${rank}/10</h3><p class="muted">Permanently increases the chance that future candidates have Uncommon, Rare, Epic, Legendary, or Mythic rarity.</p></div><button class="btn purple" ${rank>=10||state.gems<cost?'disabled':''} onclick="buyRecruitmentFortune(${cost})">${rank>=10?'Mastered':cost+'◆'}</button></section>`)}
function buyRecruitmentFortune(cost){const rank=state.training?.recruitLuck||0;if(rank>=10||state.gems<cost)return;state.gems-=cost;state.training.recruitLuck=rank+1;save();render()}
function renderDraft(){const candidates=(state.draftSlots||[]).flat(),selected=draftSelection.map(id=>candidates.find(h=>h.id===id)||null);$('#app').innerHTML=`<div class="shell">${header()}<section class="panel draftPanel"><div class="screenTitle"><h2>Build Your Party</h2><p class="muted">Choose each slot separately. Every class is available for both slots.</p></div><div class="partySlots">${selected.map((h,slot)=>`<section class="partySlot ${h?'filled':''}"><div class="slotNumber">SLOT ${slot+1}</div>${h?heroCard(h):'<div class="emptySlot">Choose an adventurer</div>'}<button class="btn ${h?'':'primary'}" onclick="openDraftSlot(${slot})">${h?'Change Slot '+(slot+1):'Choose Slot '+(slot+1)}</button></section>`).join('')}</div><div class="actions" style="justify-content:center"><button class="btn" onclick="delete state.draftSlots;render()">Cancel</button><button class="btn primary" ${selected.some(h=>!h)?'disabled':''} onclick="startRun()">Begin Expedition</button></div></section></div>`}
function renderRun(){const r=state.run;if(r.mode==='map')return renderMap();if(r.mode==='combat')return renderCombat();if(r.mode==='reward')return renderReward();if(r.mode==='recruit')return renderRecruit();if(r.mode==='inventory')return renderRunInventory();return renderMap()}
function openRunInventory(){const r=state.run;if(!r)return;if(r.mode!=='inventory'){r.returnMode=r.mode==='combat'?'combat':r.mode;r.mode='inventory'}else{r.mode=r.returnMode||'map';delete r.returnMode}save();render()}
function equippedOwner(item){return state.run.heroes.find(h=>Object.values(h.gear||{}).some(it=>it?.id===item.id))}
function consumableInventoryHtml(){const r=state.run;r.consumables=r.consumables||{};const owned=Object.entries(r.consumables).filter(([,count])=>count>0);return `<section class="consumableInventory"><h3>Combat Consumables</h3><p class="muted">Consumables can be activated from the combat screen.</p><div class="consumableGrid">${owned.length?owned.map(([id,count])=>{const c=CONSUMABLES[id];return `<article class="consumableCard"><span>${c.icon}</span><div><b>${c.name} ×${count}</b><p class="muted">${c.desc}</p></div></article>`}).join(''):'<div class="emptyState">No consumables carried.</div>'}</div></section>`}
function renderRunInventory(){const r=state.run;r.inventory=r.inventory||[];return `<div class="grid inventoryScreen"><section class="panel"><div class="screenTitle"><div class="eyebrow">RUN LOADOUT</div><h2>Inventory</h2><p class="muted">Inspect equipment and assign it to any compatible adventurer.</p></div>${consumableInventoryHtml()}<h3>Equipment</h3><div class="inventoryGrid">${r.inventory.length?r.inventory.map(it=>{const owner=equippedOwner(it);return `<article class="inventoryCard">${itemArt(it)}<div><div class="name rarity-${it.rarity}">${it.name}</div><div class="muted">Tier ${it.tier} · ${it.rarity} ${it.slot}</div><div class="itemStats">${itemStatLines(it).map(s=>`<span>${s}</span>`).join('')}</div>${owner?`<div class="equippedTag">Equipped by ${owner.name}</div>`:''}<div class="actions"><button class="btn" onclick="inspectInventoryItem(${it.id})">Inspect</button><button class="btn gold" onclick="chooseInventoryTarget(${it.id})">${owner?'Reassign':'Equip'}</button></div></div></article>`}).join(''):'<div class="emptyState">No equipment recovered yet.</div>'}</div></section>${renderSidebar()}</div>`}
function inspectInventoryItem(id){const it=state.run.inventory.find(x=>x.id===id);if(!it)return;const owner=equippedOwner(it);showOverlay(it.name,`<div class="selectedItem">${itemArt(it)}<div><div class="name rarity-${it.rarity}">${it.name}</div><div class="muted">Tier ${it.tier} · ${it.rarity} ${it.slot}${it.armorClass?' · '+it.armorClass:''}</div><div class="itemStats">${itemStatLines(it).map(s=>`<span>${s}</span>`).join('')}</div></div></div><p class="muted">${owner?'Equipped by '+owner.name:'Currently unequipped.'}</p><div class="actions"><button class="btn" onclick="closeOverlay()">Close</button><button class="btn gold" onclick="closeOverlay();chooseInventoryTarget(${it.id})">${owner?'Reassign':'Equip'}</button></div>`)}
function chooseInventoryTarget(id){const item=state.run.inventory.find(x=>x.id===id);if(!item)return;const heroes=state.run.heroes.filter(h=>h.hp>0);showOverlay('Equip '+item.name,`<div class="selectedItem">${itemArt(item)}<div><div class="name rarity-${item.rarity}">${item.name}</div><div class="itemStats">${itemStatLines(item).map(s=>`<span>${s}</span>`).join('')}</div></div></div><div class="equipGrid">${heroes.map(h=>{const old=h.gear[item.slot],allowed=canEquip(h,item);return `<button class="choice equipChoice" ${allowed?'':'disabled'} onclick="equipInventoryItem(${item.id},${h.id})">${img('classes/'+CLASSES[h.class].icon)}<strong>${h.name}</strong><div class="muted">${allowed?h.class:h.class+' · Cannot equip'}</div><div class="gearCompare"><span>${old?.name||'Empty slot'}</span>${allowed?statComparison(item,old):'<b class="loss">Incompatible</b>'}</div></button>`}).join('')}</div><div class="actions"><button class="btn" onclick="closeOverlay()">Cancel</button></div>`)}
function boonDescription(p){return p.desc||PERKS.find(x=>x[0]===p.name)?.[1]||'A party-wide blessing for this expedition.'}
function groupedBoons(){const groups=new Map();(state.run?.perks||[]).forEach(p=>{const current=groups.get(p.name)||{...p,count:0,total:0};current.count++;current.total+=(p.value||0);groups.set(p.name,current)});return[...groups.values()]}
function boonTotalDescription(p){const labels={attack:'Party Attack',hp:'Party maximum HP',speed:'Party Initiative',crit:'Critical Chance',heal:'Post-battle healing',gold:'Gold rewards'},percent=['attack','hp','speed','crit','heal','gold'].includes(p.type);return `${labels[p.type]||'Total effect'}: +${percent?Math.round(p.total*100)+'%':p.total}.`}
function inspectRelic(id){const relic=RELICS.find(x=>x[0]===id);if(relic)showOverlay(relic[1],`<div class="effectInspect"><span class="effectGlyph">⬡</span><p>${relic[2]}</p><p class="muted">Party Relic · Active for the rest of this run.</p></div>`)}
function inspectBoon(name){const boon=groupedBoons().find(p=>p.name===name);if(boon)showOverlay(`${boon.name} ×${boon.count}`,`<div class="effectInspect"><span class="effectGlyph">◆</span><p>${boonDescription(boon)}</p><p><b>${boonTotalDescription(boon)}</b></p><p class="muted">Run Boon · Chosen ${boon.count} ${boon.count===1?'time':'times'}.</p></div>`)}
function renderSidebar(){const r=state.run;r.relics=r.relics||[];const boons=groupedBoons();return `<aside class="panel"><h3>Expedition Party</h3><div class="heroGrid">${r.heroes.map(heroCard).join('')}</div><h3 style="margin-top:15px">Party Relics</h3><div class="sidebarEffects">${r.relics.length?r.relics.map(id=>`<button class="sidebarEffect relicEffect" onclick="inspectRelic('${id}')">⬡ <span>${RELICS.find(x=>x[0]===id)?.[1]||id}</span></button>`).join(''):'<div class="muted">No relics yet.</div>'}</div><h3 style="margin-top:15px">Run Boons</h3><div class="sidebarEffects">${boons.length?boons.map(p=>`<button class="sidebarEffect boonEffect" onclick="inspectBoon('${p.name}')">◆ <span>${p.name}${p.count>1?' ×'+p.count:''}</span></button>`).join(''):'<div class="muted">No boons yet.</div>'}</div><div class="actions"><button class="btn danger" onclick="confirmAbandon()">Abandon Run</button></div></aside>`}
function renderMap(){const r=state.run,reg=REGIONS[r.region],nodes=normalizeRegionMap(r),encounters=nodes.length,ascending=[...nodes].map((row,rowIndex)=>({row,rowIndex})).reverse();return `<div class="grid runMapGrid"><section class="panel map" style="background-image:url('${ASSET}backgrounds/${reg.bg}')"><div class="regionHead"><div class="eyebrow">REGION ${r.region+1} · STEP ${Math.min(encounters+1,r.step+1)}/${encounters+1}</div><h2>${reg.name}</h2><p class="muted">The expedition begins below and climbs toward the boss.</p></div><div class="mapScroll"><div class="path"><div class="pathRow singlePathRow"><button class="node ${r.step>=encounters?'current':''}" ${r.step>=encounters?'':'disabled'} onclick="chooseNode('boss')"><span class="nodeIcon">♛</span><span class="nodeName">${reg.boss[0]}</span><div class="nodeDesc">Region Boss</div></button></div>${ascending.map(({row,rowIndex})=>`<div class="pathRow ${row.length===1?'singlePathRow':''}">${row.map(type=>{const active=rowIndex===r.step,lockedOut=active&&r.lockedNodeType&&r.lockedNodeType!==type,n=NODE_INFO[type];return `<button class="node ${active&&!lockedOut?'current':rowIndex<r.step?'done':lockedOut?'lockedOut':''}" ${active&&!lockedOut?'':`disabled`} onclick="chooseNode('${type}')"><span class="nodeIcon">${n[0]}</span><span class="nodeName">${n[1]}</span><div class="nodeDesc">${lockedOut?'Another path was chosen.':n[2]}</div></button>`}).join('')}</div>`).join('')}</div></div></section>${renderSidebar()}</div>`}
function focusCurrentMapNode(){const scroller=$('.mapScroll'),current=scroller?.querySelector('.node.current');if(!scroller||!current)return;const scrollBox=scroller.getBoundingClientRect(),nodeBox=current.getBoundingClientRect();scroller.scrollTop+=nodeBox.top-scrollBox.top-(scroller.clientHeight-current.offsetHeight)/2}
function chooseNode(type){const r=state.run;if(r.lockedNodeType&&r.lockedNodeType!==type)return;if(!r.lockedNodeType){r.lockedNodeType=type;save();render()}if(type==='combat'||type==='elite'||type==='boss')return beginCombat(type);if(type==='camp'){r.heroes.forEach(h=>h.hp=Math.min(h.maxHp,h.hp+h.maxHp*.35));toast('The party recovered 35% health.');return advanceNode()}if(type==='treasure')return treasureEvent();if(type==='merchant')return merchantEvent();if(type==='shrine')return abilityShrine();if(type==='relic')return relicVault();return storyEvent()}
function enemyUnit(name,icon,level,elite=false,boss=false){const scale=1+(level-1)*.22,maxHp=Math.round((boss?335:elite?150:105)*scale);return{id:uid(),name,icon,level,maxHp,hp:maxHp,atk:Math.round((boss?22:elite?16:12)*scale),speed:(boss?.98:elite?.94:.85)*.35,slowAttackMigration:true,attackSpeedVersion:2,statuses:{},boss,elite,progress:0}}
function beginCombat(type){const r=state.run,reg=REGIONS[r.region];if(r.enemyLevelBase==null)r.enemyLevelBase=r.region>0?1+(r.region-1)*5+12:0;const level=r.enemyLevelBase+r.step+1,boss=type==='boss',elite=type==='elite',count=boss?1:Math.min(4,2+Math.floor(r.region/2)+(elite?1:0));const enemies=Array.from({length:count},()=>{const e=boss?reg.boss:pick(reg.enemies);return enemyUnit(e[0],e[1],level,elite,boss)});r.heroes.forEach(h=>{ensureHeroResources(h);h.abilityCooldown=0;h.damage=0;h.damageTaken=0;h.healing=0;if(hasRelic('guardianBell'))h.ward=4});assignPartyFormation(r.heroes);r.battle={id:uid(),type,enemies,heroProgress:{},phoenixUsed:false,log:[`${boss?'Boss battle':'Battle'} begins.`]};r.mode='combat';save();render()}
function itemStats(it){const out=Object.fromEntries(ITEM_STAT_KEYS.map(k=>[k,0]));if(!it)return out;if(it.stat)out[it.stat]=(out[it.stat]||0)+(it.value||0);if(it.secondaryStat)out[it.secondaryStat]=(out[it.secondaryStat]||0)+(it.secondaryValue||0);if(it.tertiaryStat)out[it.tertiaryStat]=(out[it.tertiaryStat]||0)+(it.tertiaryValue||0);Object.entries(it.extraStats||{}).forEach(([k,v])=>out[k]=(out[k]||0)+v);ITEM_STAT_KEYS.forEach(k=>{if(k==='critChance')out[k]+=it.weaponCritChance||it[k]||0;else if(k!=='hp'&&k!=='str'&&k!=='dex'&&k!=='int'&&k!=='def'&&k!=='mdef'&&k!=='mana'&&k!=='manaRegen'&&k!=='regen'&&k!=='attackSpeed'&&k!=='lifesteal'&&k!=='fire'&&k!=='ice'&&k!=='poison'&&k!=='lightning'&&k!=='holy'&&k!=='dark')out[k]+=it[k]||0});return out}
function gearStats(h){const out=Object.fromEntries(ITEM_STAT_KEYS.map(k=>[k,0]));Object.values(h.gear||{}).filter(Boolean).forEach(it=>{const stats=itemStats(it);ITEM_STAT_KEYS.forEach(k=>out[k]+=stats[k]||0)});['str','dex','int','def','mdef'].forEach(k=>out[k]+=trainingRank(k)*2);out.critDamage+=trainingRank('critDamage')*.04;out.statusChance+=trainingRank('statusChance')*.02;const raceFlat=RACE_DATA[h.race]?.flat||{};out.attackSpeed+=(raceFlat.attackSpeed||0)*100;out.manaRegen+=raceFlat.manaRegen||0;out.regen+=raceFlat.regen||0;if(state.run){if(hasRelic('warDrum'))out.attackSpeed+=18;if(hasRelic('hourglass'))out.cooldownReduction+=.2;if(hasRelic('bloodChalice'))out.lifesteal+=5;if(hasRelic('moonwell'))out.manaRegen+=2;if(hasRelic('ironIdol'))out.def+=5;if(state.run.battle?.consumableLifesteal)out.lifesteal+=state.run.battle.consumableLifesteal}if(h.ward>0)out.def+=20;return out}
function heroCombatSpeed(h,gs=gearStats(h)){const boon=state.run?.perks.filter(p=>p.type==='speed').reduce((a,p)=>a+p.value,0)||0;return h.speed*(1+gs.attackSpeed/100+boon)}
function heroThreat(h){const sub=(SUBCLASS_DATA[h.class]||[]).find(x=>x.id===h.subclass),gear=gearStats(h);return Math.max(.1,(CLASSES[h.class].threat||1)+(sub?.threatBonus||0)+(gear.threatBonus||0))}
function assignPartyFormation(heroes){const frontCount=Math.max(1,Math.ceil(heroes.length*.4)),ranked=[...heroes].sort((a,b)=>{const durable=x=>(['Warrior','Paladin'].includes(x.class)?2:0)+heroThreat(x)+heroSheetStats(x).def/250+heroSheetStats(x).block/20;return durable(b)-durable(a)}),frontIds=new Set(ranked.slice(0,frontCount).map(h=>h.id));heroes.forEach(h=>h.row=frontIds.has(h.id)?'front':'back');return heroes}
function threatTarget(targets){const total=targets.reduce((sum,h)=>sum+Math.max(.01,heroThreat(h)),0);let roll=Math.random()*total;for(const h of targets){roll-=Math.max(.01,heroThreat(h));if(roll<=0)return h}return targets[targets.length-1]}
function enemyTarget(heroes){const front=heroes.filter(h=>h.row==='front'),back=heroes.filter(h=>h.row!=='front');if(!front.length)return threatTarget(back.length?back:heroes);if(!back.length)return threatTarget(front);return threatTarget(Math.random()<.9?front:back)}
function itemStatLines(it){const lines=[];if(it.weaponPower)lines.push(`+${it.weaponPower} Attack`);const stats=itemStats(it);ITEM_STAT_KEYS.forEach(k=>{const v=stats[k];if(!v)return;lines.push(`${v>0?'+':''}${PERCENT_STATS.has(k)?Math.round(v*100)+'%':v} ${STAT_LABELS[k]||k}`)});return lines}
function effectiveAtk(h){const perk=state.run?.perks.filter(p=>p.type==='attack').reduce((a,p)=>a+p.value,0)||0,gs=gearStats(h),primary=CLASSES[h.class].stat.toLowerCase(),sheet=heroSheetStats(h);return Math.round((h.atk+(h.gear.Weapon?.weaponPower||h.gear.Weapon?.power||0)+sheet[primary]*.75)*(1+perk+gs.damageBonus))}
function startBattleLoop(){if(battleTimer)return;const battle=state.run.battle;if(battle.resolved){setTimeout(()=>completeBattleVictory(battle.id),Math.max(0,2000-(Date.now()-(battle.victoryAt||Date.now()))));return}battle.enemies.forEach(e=>{e.statuses=e.statuses||{};if(e.attackSpeedVersion!==2){e.speed*=e.slowAttackMigration?.35/.65:.35;e.slowAttackMigration=true;e.attackSpeedVersion=2}});lastCombatTick=performance.now();battleTimer=setInterval(runCombatStep,260);battleFrame=requestAnimationFrame(animateCombatMeters)}
function processRelicEffects(){const r=state.run,b=r?.battle;if(!b)return;if(hasRelic('phoenixFeather')&&!b.phoenixUsed){const fallen=r.heroes.find(h=>h.hp<=0);if(fallen){fallen.hp=Math.round(fallen.maxHp*.35);b.phoenixUsed=true;b.log.unshift(`${fallen.name} rises again through the Phoenix Feather!`)}}}
function runCombatStep(){processOngoingEffects();const heroes=state.run?.heroes||[],before=new Map(heroes.map(h=>[h.id,h.hp])),cooldowns=new Map(heroes.map(h=>[h.id,h.abilityCooldown||0]));combatTick();processRelicEffects();if(hasRelic('echoStone'))heroes.forEach(h=>{if((cooldowns.get(h.id)||0)<=0&&(h.abilityCooldown||0)>0&&Math.random()<.25){h.abilityCooldown=0;state.run.battle?.log.unshift(`${h.name}'s ability echoes through the Echo Stone.`)}});heroes.forEach(h=>h.damageTaken+=Math.max(0,(before.get(h.id)||0)-h.hp));updateCombatReport()}
function applyHealing(source,target,amount){const before=target.hp;target.hp=Math.min(target.maxHp,target.hp+amount);const actual=Math.max(0,target.hp-before);source.healing=(source.healing||0)+actual;return actual}
function processOngoingEffects(){const r=state.run,b=r?.battle;if(!b)return;b.enemies.forEach(e=>{const burn=e.statuses?.burning,el=$(`#unit-${e.id}`);if(e.frozenFor>0){e.frozenFor=Math.max(0,e.frozenFor-.26);el?.classList.add('frozen')}else el?.classList.remove('frozen');if(burn&&e.hp>0){const damage=Math.min(e.hp,burn.power*.26),source=r.heroes.find(h=>h.id===burn.sourceId);e.hp-=damage;if(source)source.damage+=damage;burn.time-=.26;el?.classList.add('burning');if(burn.time<=0){delete e.statuses.burning;el?.classList.remove('burning')}}});r.heroes.forEach(h=>{const el=$(`#unit-${h.id}`);if(h.renewUntil>0&&h.hp>0){const source=r.heroes.find(x=>x.id===h.renewSource)||h;applyHealing(source,h,h.maxHp*.02*.26);h.renewUntil-=.26;el?.classList.add('renewing')}else el?.classList.remove('renewing');if(h.ward>0){h.ward-=.26;el?.classList.add('warded')}else el?.classList.remove('warded')})}
function animateCombatMeters(now){const r=state.run,b=r?.battle;if(!b||r.mode!=='combat')return;const elapsed=Math.min(.26,(now-lastCombatTick)/1000);r.heroes.forEach(h=>{const e=$(`#unit-${h.id}`);if(!e||h.hp<=0)return;const gs=gearStats(h),speed=heroCombatSpeed(h,gs),attack=Math.min(4,(b.heroProgress[h.id]||0)+speed*elapsed/0.26),cooldown=Math.max(0,(h.abilityCooldown||0)-elapsed*(1+gs.cooldownReduction)),bars=e.querySelectorAll('.bar i');if(bars[1])bars[1].style.width=clamp(h.mana/h.maxMana*100,0,100)+'%';if(bars[2])bars[2].style.width=clamp((1-cooldown/ABILITIES[h.class].cooldown)*100,0,100)+'%';if(bars[3])bars[3].style.width=clamp(attack/4*100,0,100)+'%'});b.enemies.forEach(u=>{const e=$(`#unit-${u.id}`),bar=e?.querySelectorAll('.bar i')[1];if(bar)bar.style.width=clamp(((u.progress||0)+u.speed*elapsed/0.26)/4*100,0,100)+'%'});battleFrame=requestAnimationFrame(animateCombatMeters)}
function hasAugment(h,id){return (h.augments||[]).includes(id)}function hasRelic(id){return (state.run?.relics||[]).includes(id)}
function abilityCost(h){return Math.round(ABILITIES[h.class].cost*(hasAugment(h,'efficient')?.7:1))}
function abilityCooldown(h){return ABILITIES[h.class].cooldown*(hasAugment(h,'tempo')?.75:1)*(hasRelic('hourglass')?.8:1)}
function castHeroAbility(h,livingH,livingE,b){const a=ABILITIES[h.class],gs=gearStats(h),cost=abilityCost(h);if(!a||h.abilityCooldown>0||h.mana<cost)return false;const wounded=livingH.some(x=>x.hp/x.maxHp<.9);if((h.class==='Priest'||h.class==='Paladin')&&!wounded)return false;h.mana-=cost;h.abilityCooldown=abilityCooldown(h);let message='',power=hasAugment(h,'mighty')?1.35:1;if(h.class==='Priest'){const target=[...livingH].sort((x,y)=>x.hp/x.maxHp-y.hp/y.maxHp)[0],heal=Math.round(effectiveAtk(h)*1.8*power*(1+gs.healingPower+gs.healBonus)),actual=applyHealing(h,target,heal);if(hasAugment(h,'renew')){target.renewUntil=5;target.renewSource=h.id}message=`${h.name} casts Mend on ${target.name} for ${Math.round(actual)}.`}else if(h.class==='Paladin'){const target=[...livingH].sort((x,y)=>x.hp/x.maxHp-y.hp/y.maxHp)[0],heal=Math.round(effectiveAtk(h)*1.15*power*(1+gs.healingPower+gs.healBonus)),actual=applyHealing(h,target,heal);if(hasAugment(h,'aegis'))livingH.forEach(x=>x.ward=1);message=`${h.name} invokes Holy Guard, restoring ${Math.round(actual)} health.`}else{const targets=(h.class==='Warrior'||h.class==='Ranger')?livingE.filter(x=>x.hp>0):[pick(livingE.filter(x=>x.hp>0))];const mult=({Warrior:1.05,Ranger:.9,Rogue:2.15,Mage:2}[h.class]||1.5)*power*(1+gs.elementalDamage+(gs.statusChance+(hasRelic('emberHeart')?.2:0))*.25);let total=0,killed=false;targets.forEach(target=>{const dmg=Math.round(effectiveAtk(h)*mult*(.9+Math.random()*.2));target.hp-=dmg;total+=dmg;if(hasAugment(h,'burn'))target.statuses.burning={time:5,power:Math.max(1,Math.round(dmg*.12)),sourceId:h.id};if(target.hp<=0){h.kills++;killed=true}});if(hasAugment(h,'suppress'))livingE.forEach(e=>e.progress=Math.max(0,e.progress-1));if(hasAugment(h,'blood'))applyHealing(h,h,total*.15);if(hasAugment(h,'execute')&&killed)h.abilityCooldown=0;h.damage+=total;message=`${h.name} uses ${a.name} for ${total} damage${targets.length>1?' across the enemy line':''}.`}b.log.unshift(message);return true}
function combatTick(){lastCombatTick=performance.now();const r=state.run,b=r?.battle;if(!r||r.mode!=='combat'||!b)return;const livingH=r.heroes.filter(h=>h.hp>0),livingE=b.enemies.filter(e=>e.hp>0);if(!livingH.length)return endRun(false);if(!livingE.length)return winBattle();b.manaRegenElapsed=(b.manaRegenElapsed||0)+.26;const manaRegenTick=b.manaRegenElapsed>=5;if(manaRegenTick)b.manaRegenElapsed-=5;r.heroes.forEach(h=>{if(h.hp<=0)return;const gs=gearStats(h);if(manaRegenTick)h.mana=Math.min(h.maxMana,h.mana+h.manaRegen+gs.manaRegen);h.hp=Math.min(h.maxHp,h.hp+gs.regen*.26);h.abilityCooldown=Math.max(0,(h.abilityCooldown||0)-.26*(1+gs.attackSpeed/200));if(castHeroAbility(h,livingH,livingE,b))return;b.heroProgress[h.id]=(b.heroProgress[h.id]||0)+h.speed*(1+gs.attackSpeed/100)*(1+r.perks.filter(p=>p.type==='speed').reduce((a,p)=>a+p.value,0));if(b.heroProgress[h.id]>=4){b.heroProgress[h.id]=0;const target=pick(livingE.filter(x=>x.hp>0)),crit=Math.random()<h.crit+gs.critChance+r.perks.filter(p=>p.type==='crit').reduce((a,p)=>a+p.value,0),variance=.14+(gs.damageVariance||0),dmg=Math.round(effectiveAtk(h)*(crit?1.75+gs.critDamage:1)*(1-variance+Math.random()*variance*2));target.hp-=dmg;h.hp=Math.min(h.maxHp,h.hp+dmg*gs.lifesteal/100);h.damage+=dmg;if(target.hp<=0)h.kills++;b.log.unshift(`${h.name} hits ${target.name} for ${dmg}${crit?' critical':''}.`)}});b.enemies.forEach(e=>{if(e.hp<=0)return;e.progress+=e.speed;if(e.progress>=4){e.progress=0;const target=enemyTarget(livingH),gs=gearStats(target);if(Math.random()<gs.parry){b.log.unshift(`${target.name} parries ${e.name}.`);return}const dmg=Math.max(1,Math.round(e.atk*(.82+Math.random()*.3)*100/(100+gs.def*3)));target.hp-=dmg;b.log.unshift(`${e.name} hits ${target.name} for ${dmg}.`)}});b.log=b.log.slice(0,14);save();updateCombatDom()}
function unitCard(u,enemy=false){const hp=clamp(u.hp/u.maxHp*100,0,100),path=enemy?'enemies/'+u.icon:'classes/'+CLASSES[u.class].icon,attack=enemy?u.progress||0:state.run.battle.heroProgress[u.id]||0;if(enemy)return `<div class="unit enemy ${u.hp<=0?'dead':''}" id="unit-${u.id}"><div class="unitName">Lv. ${u.level} · ${u.name}</div>${img(path)}<div class="meterLabel"><span>Health</span><span class="hpText">${Math.max(0,Math.ceil(u.hp))}/${u.maxHp}</span></div><div class="bar"><i style="width:${hp}%"></i></div><div class="meterLabel"><span>Attack</span><span>incoming</span></div><div class="bar attackBar"><i style="width:${clamp(attack/4*100,0,100)}%"></i></div></div>`;const a=ABILITIES[u.class],mana=clamp(u.mana/u.maxMana*100,0,100),cd=clamp((1-(u.abilityCooldown||0)/a.cooldown)*100,0,100);return `<div class="unit ${u.hp<=0?'dead':''}" id="unit-${u.id}"><div class="unitName">${u.name}<small>${u.class} · ${u.row==='front'?'Front':'Back'} · ${heroThreat(u).toFixed(2)} Threat</small></div>${img(path)}<div class="meterLabel"><span>Health</span><span class="hpText">${Math.max(0,Math.ceil(u.hp))}/${u.maxHp}</span></div><div class="bar"><i style="width:${hp}%"></i></div><div class="meterLabel"><span>Mana</span><span class="manaText">${Math.floor(u.mana)}/${u.maxMana}</span></div><div class="bar mana"><i style="width:${mana}%"></i></div><div class="abilityLine"><span>${a.name} · ${a.cost} MP</span><span class="cooldownText">${u.abilityCooldown>0?u.abilityCooldown.toFixed(1)+'s':'READY'}</span></div><div class="bar cooldown"><i style="width:${cd}%"></i></div><div class="bar attackBar" title="Basic attack timer"><i style="width:${clamp(attack/4*100,0,100)}%"></i></div></div>`}
function combatReportRows(){return state.run.heroes.map(h=>`<div class="reportRow" id="report-${h.id}"><strong>${h.name}</strong><span><small>Damage</small><b data-report="damage">${Math.round(h.damage)}</b></span><span><small>Taken</small><b data-report="taken">${Math.round(h.damageTaken)}</b></span><span><small>Healing</small><b data-report="healing">${Math.round(h.healing)}</b></span></div>`).join('')}
function combatConsumablesHtml(){const r=state.run;r.consumables=r.consumables||{};const owned=Object.entries(r.consumables).filter(([,count])=>count>0);return `<div class="combatConsumables"><h3>Consumables</h3>${owned.length?owned.map(([id,count])=>{const c=CONSUMABLES[id];return `<button class="consumableButton" onclick="useConsumable('${id}')"><span>${c.icon}</span><b>${c.name}</b><small>×${count}</small></button>`}).join(''):'<span class="muted">No consumables available.</span>'}</div>`}
function useConsumable(id){const r=state.run,c=CONSUMABLES[id];r.consumables=r.consumables||{};if(r.mode!=='combat'||!c||(r.consumables[id]||0)<=0)return;const preserved=hasRelic('alchemySatchel')&&Math.random()<.35;if(!preserved)r.consumables[id]--;const livingH=r.heroes.filter(h=>h.hp>0),livingE=r.battle.enemies.filter(e=>e.hp>0);if(id==='healingPotion'){const h=[...livingH].sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];if(h)applyHealing(h,h,h.maxHp*.45)}else if(id==='regenTonic')livingH.forEach(h=>{h.renewUntil=Math.max(h.renewUntil||0,8);h.renewSource=h.id});else if(id==='vampireElixir')r.battle.consumableLifesteal=Math.max(r.battle.consumableLifesteal||0,12);else if(id==='fireballScroll'){const damage=70+r.region*35;livingE.forEach(e=>e.hp=Math.max(0,e.hp-damage));r.battle.log.unshift(`A Fireball Scroll scorches every enemy for ${damage}.`)}else if(id==='frostScroll'){livingE.forEach(e=>{e.progress=0;e.frozenFor=4;e.speedBeforeFreeze=e.speed;e.speed=0});setTimeout(()=>livingE.forEach(e=>{if(e.speedBeforeFreeze!=null){e.speed=e.speedBeforeFreeze;delete e.speedBeforeFreeze;e.frozenFor=0}}),4000)}toast(`${c.name} used${preserved?' — the Alchemy Satchel preserved it':''}.`);save();render()}
function renderCombat(){const r=state.run,b=r.battle,reg=REGIONS[r.region];r.heroes.forEach(ensureHeroResources);b.heroProgress=b.heroProgress||{};return `<section class="panel combatField" style="background-image:url('${ASSET}backgrounds/${reg.bg}')"><div class="regionHead"><div class="eyebrow">${b.type==='boss'?'REGION BOSS':b.type==='elite'?'ELITE BATTLE':'BATTLE'}</div><h2>${reg.name}</h2></div><div class="combatSides"><div class="combatSide">${r.heroes.map(h=>unitCard(h)).join('')}</div><div class="combatSide">${b.enemies.map(e=>unitCard(e,true)).join('')}</div></div>${combatConsumablesHtml()}<div class="combatBottom"><div class="combatLog">${b.log.join('<br>')}</div><aside class="combatReport"><h3>Battle Report</h3>${combatReportRows()}</aside></div></section>`}
function updateCombatReport(){state.run?.heroes.forEach(h=>{const row=$(`#report-${h.id}`);if(!row)return;row.querySelector('[data-report="damage"]').textContent=Math.round(h.damage);row.querySelector('[data-report="taken"]').textContent=Math.round(h.damageTaken);row.querySelector('[data-report="healing"]').textContent=Math.round(h.healing)})}
function updateCombatDom(){const r=state.run,b=r?.battle;if(!b)return;[...r.heroes,...b.enemies].forEach(u=>{const e=$(`#unit-${u.id}`);if(!e)return;const bars=e.querySelectorAll('.bar i'),enemy=!u.class,attack=enemy?u.progress||0:b.heroProgress[u.id]||0;if(bars[0])bars[0].style.width=clamp(u.hp/u.maxHp*100,0,100)+'%';const hpText=e.querySelector('.hpText');if(hpText)hpText.textContent=`${Math.max(0,Math.ceil(u.hp))}/${u.maxHp}`;if(enemy){if(bars[1])bars[1].style.width=clamp(attack/4*100,0,100)+'%'}else{const a=ABILITIES[u.class];if(bars[1])bars[1].style.width=clamp(u.mana/u.maxMana*100,0,100)+'%';if(bars[2])bars[2].style.width=clamp((1-(u.abilityCooldown||0)/a.cooldown)*100,0,100)+'%';if(bars[3])bars[3].style.width=clamp(attack/4*100,0,100)+'%';e.querySelector('.manaText').textContent=`${Math.floor(u.mana)}/${u.maxMana}`;e.querySelector('.cooldownText').textContent=u.abilityCooldown>0?u.abilityCooldown.toFixed(1)+'s':'READY'}e.classList.toggle('dead',u.hp<=0)});const log=$('.combatLog');if(log)log.innerHTML=b.log.join('<br>')}
function heroXpNeeded(level){const n=Math.max(0,(level||1)-1);return Math.round(100+n*85+n*n*6)}
function levelBattleParty(){const target=currentPartyLevel()+1;return state.run.heroes.map(h=>{h.xp=0;while(h.level<target){const oldNatural=naturalMaxHp(h);h.level++;const hpGain=Math.max(1,naturalMaxHp(h)-oldNatural);h.maxHp+=hpGain;if(h.hp>0)h.hp=Math.min(h.maxHp,h.hp+hpGain);if(h.level>=10&&!h.subclass){const options=SUBCLASS_DATA[h.class]||[];if(options.length)h.subclass=pick(options).id}}return h})}
function currentPartyLevel(){return Math.max(1,...(state.run?.heroes||[]).map(h=>h.level||1))}
function winBattle(){const r=state.run,b=r?.battle;if(!b||b.resolved)return;clearInterval(battleTimer);battleTimer=null;cancelAnimationFrame(battleFrame);battleFrame=null;b.id=b.id||uid();b.resolved=true;b.victoryAt=Date.now();b.log.unshift('Victory! Final battle report shown for 2 seconds.');save();render();setTimeout(()=>completeBattleVictory(b.id),2000)}
function completeBattleVictory(battleId){const r=state.run,b=r?.battle;if(!r||r.mode!=='combat'||!b||b.id!==battleId||!b.resolved)return;const boss=b.type==='boss',elite=b.type==='elite';r.encounters++;const gold=Math.round((18+r.region*22+r.step*6)*(elite?1.8:boss?3:1)*(1+runBoonTotal('gold')));r.gold+=gold;const leveled=levelBattleParty();r.heroes.forEach(h=>{if(h.hp>0)h.hp=Math.min(h.maxHp,h.hp+h.maxHp*runBoonTotal('heal'))});if(leveled.length)toast(`The whole party reached level ${currentPartyLevel()}!`);if(boss){r.enemyLevelBase=Math.max(...b.enemies.map(e=>e.level));state.trophies.push(`${REGIONS[r.region].boss[0]} defeated`);state.gearTierUnlocked=Math.max(state.gearTierUnlocked||1,Math.min(REGIONS.length,r.region+2));r.battle=null;if(r.region===REGIONS.length-1)return endRun(true);toast(`Gear Tier ${state.gearTierUnlocked} unlocked.`);r.mode='recruit';r.recruitChoices=classRoster(currentPartyLevel());save();render();return}r.pendingReward=makeRewards();r.pendingEliteRelics=elite?makeEliteRelicRewards():null;r.battle=null;r.mode='reward';save();render()}
function equipmentPrimaryValue(base,tier,rarity){return Math.round(base*Math.pow(1.6,Math.max(0,tier-1))*(ITEM_RARITY_MULTIPLIER[rarity]||1))}
function rollRarity(tier){const r=Math.random(),tierBonus=Math.min(.018,Math.max(0,tier-1)*.0015),mythic=Math.min(.02,.00008+tierBonus*.03),legendary=Math.max(mythic,Math.min(.08,.0007+tierBonus*.12)),epic=Math.max(legendary,Math.min(.25,.004+tierBonus*.35)),rare=Math.max(epic,Math.min(.60,.022+tierBonus)),uncommon=Math.max(rare,Math.min(.88,.14+tierBonus*2.2));return r<mythic?'Mythic':r<legendary?'Legendary':r<epic?'Epic':r<rare?'Rare':r<uncommon?'Uncommon':'Common'}
function applyRarityAffixes(it){const rarity=it.rarity,simple={Common:0,Uncommon:1,Rare:2,Epic:3,Legendary:4,Mythic:5}[rarity]||0;if(simple>0&&it.stat){if(it.stat==='regen'||it.stat==='manaRegen')it.value+=Math.max(1,Math.floor(simple/2));else if(it.stat==='mana')it.value+=simple*2;else if(it.stat==='lifesteal')it.value+=simple;else it.value+=simple*2}if(['Rare','Epic','Legendary','Mythic'].includes(rarity)){const pool=['lifesteal','regen','mana','manaRegen','attackSpeed','fire','ice','poison','lightning','holy','dark','str','dex','int','mdef'];it.secondaryStat=pick(pool);it.secondaryValue=it.secondaryStat==='lifesteal'?2+simple:(it.secondaryStat==='regen'||it.secondaryStat==='manaRegen')?Math.max(1,Math.floor(1+simple/2)):it.secondaryStat==='mana'?4+simple*2:it.secondaryStat==='attackSpeed'?2+simple:['fire','ice','poison','lightning','holy','dark'].includes(it.secondaryStat)?4+simple*2:1+simple}if(['Legendary','Mythic'].includes(rarity)){const pool=['lifesteal','regen','mana','manaRegen','attackSpeed','fire','ice','poison','lightning','holy','dark','def','mdef'];it.tertiaryStat=pick(pool);it.tertiaryValue=it.tertiaryStat==='lifesteal'?4+simple:(it.tertiaryStat==='regen'||it.tertiaryStat==='manaRegen')?2+Math.floor(simple/2):it.tertiaryStat==='mana'?6+simple*2:it.tertiaryStat==='attackSpeed'?3+simple:6+simple*2}if(rarity==='Mythic')it.mythicEffect=pick(['Executioner','Phoenix','Stormheart','Bloodbound','Frostborn']);it.power=(it.power||0)+simple*8+(it.secondaryValue||0)*4+(it.tertiaryValue||0)*4;return it}
