function partyCanEquip(item){return !state.run?.heroes?.length||state.run.heroes.some(h=>canEquip(h,item))}
function makeCanonicalItem(forcedRarity=null){const tier=Math.min(state.gearTierUnlocked||1,state.run.region+1),available=RECIPE_DATA.filter(r=>r[4]===tier&&r[1]!=='Material'&&r[1]!=='Rune').sort(()=>Math.random()-.5);for(const recipe of available){const item=makeRecipeItem(recipe,forcedRarity||rollRarity(tier));if(partyCanEquip(item))return item}for(let attempt=0;attempt<30;attempt++){const item=makeItem();if(partyCanEquip(item))return item}const fallback=makeItem();fallback.slot='Accessory';delete fallback.allowedClasses;return fallback}
function rollShopRarity(guaranteed=false){const r=Math.random();if(guaranteed)return r<.04?'Mythic':r<.22?'Legendary':'Epic';return r<.012?'Mythic':r<.07?'Legendary':r<.30?'Epic':r<.62?'Rare':r<.88?'Uncommon':'Common'}
function shopItemCost(item){const rarityCost={Common:36,Uncommon:65,Rare:115,Epic:210,Legendary:390,Mythic:720}[item.rarity]||36;return Math.round(rarityCost*Math.pow(item.tier||1,1.35))}
function randomUnownedRelic(){return pick(RELICS.filter(x=>!(state.run.relics||[]).includes(x[0])))}
function makeRewards(){return[{kind:'item',item:makeCanonicalItem()},{kind:'gold',amount:35+state.run.region*30},{kind:'perk',perk:pick(PERKS)}]}
function makeEliteRelicRewards(){return RELICS.filter(x=>!(state.run.relics||[]).includes(x[0])).sort(()=>Math.random()-.5).slice(0,3).map(relic=>({kind:'relic',relic}))}
function itemFolder(slot){return slot==='Weapon'?'weapons':slot==='Armor'?'armor':'accessories'}
function itemSlug(name){return String(name||'default').toLowerCase().replace(/['’]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function itemArt(it){const src=it.image?`../guildmaster/${it.image}`:`${ASSET}items/${itemFolder(it.slot)}/${itemSlug(it.name)}.png`;return `<span class="itemIcon"><img src="${src}" alt="" onerror="this.style.display='none';this.nextElementSibling.style.display='grid'"><span class="itemFallback">${it.slot==='Weapon'?'⚔':it.slot==='Armor'?'▣':'◇'}</span></span>`}
function rewardChoiceHtml(x,i){if(x.kind==='item')return `<button class="choice rewardChoice" onclick="takeReward(${i})">${itemArt(x.item)}<strong class="rarity-${x.item.rarity}">${x.item.name}</strong><div class="rewardType">Tier ${x.item.tier} · ${x.item.rarity} ${x.item.slot}</div><div class="itemStats">${itemStatLines(x.item).map(s=>`<span>${s}</span>`).join('')}</div><span class="choiceHint">Add to inventory →</span></button>`;if(x.kind==='gold')return `<button class="choice rewardChoice" onclick="takeReward(${i})"><span class="big">◉</span><strong>${x.amount} Run Gold</strong><div class="muted">Spend it now or risk carrying it home.</div><span class="choiceHint">Take reward →</span></button>`;if(x.kind==='relic')return `<button class="choice rewardChoice relicReward" onclick="takeReward(${i})"><span class="big">⬡</span><strong>${x.relic[1]}</strong><div class="muted">${x.relic[2]}</div><span class="choiceHint">Claim elite relic →</span></button>`;return `<button class="choice rewardChoice" onclick="takeReward(${i})"><span class="big">◆</span><strong>${x.perk[0]}</strong><div class="muted">${x.perk[1]} for this run.</div><span class="choiceHint">Take boon →</span></button>`}
function renderReward(){const r=state.run,relicStage=r.pendingReward.every(x=>x.kind==='relic');return `<section class="panel rewardsPanel"><div class="screenTitle"><div class="eyebrow">${relicStage?'ELITE RELIC':'VICTORY SPOILS'}</div><h2>${relicStage?'Choose One Relic':'Choose One Reward'}</h2><p class="muted">${relicStage?'The defeated elite guarded these relics. Claim one.':'Choose equipment, gold, or a run boon first.'}</p></div><div class="choiceGrid">${r.pendingReward.map(rewardChoiceHtml).join('')}</div></section>`}
function takeReward(i){const r=state.run,x=r.pendingReward[i],relicStage=x.kind==='relic';if(x.kind==='item'){r.inventory=r.inventory||[];r.inventory.push(x.item);toast(`${x.item.name} added to the run inventory.`)}else if(x.kind==='gold')r.gold+=x.amount;else if(x.kind==='relic'){r.relics=r.relics||[];r.relics.push(x.relic[0]);toast(`${x.relic[1]} joined the party relics.`)}else if(x.kind==='perk'){r.perks.push({name:x.perk[0],desc:x.perk[1],type:x.perk[2],value:x.perk[3]});if(x.perk[2]==='hp')r.heroes.forEach(h=>{const gain=Math.round(h.maxHp*x.perk[3]);h.maxHp+=gain;h.hp+=gain})}if(!relicStage&&r.pendingEliteRelics?.length){r.pendingReward=r.pendingEliteRelics;delete r.pendingEliteRelics;save();render();return}r.pendingReward=null;delete r.pendingEliteRelics;advanceNode()}
function canEquip(h,item){if(item.allowedClasses&&!item.allowedClasses.includes(h.class))return false;if(item.slot==='Weapon')return !Object.keys(ITEM_DATA.weapons).length||CLASSES[h.class].weapons?.includes(item.weaponTemplate||item.name);if(item.slot==='Armor'){const order={Light:1,Medium:2,Heavy:3};return (order[item.armorClass]||1)<=(order[CLASSES[h.class].armor]||1)}return true}
function statComparison(item,old){const next=itemStats(item),prev=itemStats(old),lines=[];if(item.weaponPower||old?.weaponPower){const d=(item.weaponPower||0)-(old?.weaponPower||old?.power||0);if(d)lines.push(`<b class="${d>0?'gain':'loss'}">${d>0?'+':''}${d} Attack</b>`)}ITEM_STAT_KEYS.forEach(k=>{const d=(next[k]||0)-(prev[k]||0);if(!d)return;lines.push(`<b class="${d>0?'gain':'loss'}">${d>0?'+':''}${PERCENT_STATS.has(k)?Math.round(d*100)+'%':d} ${STAT_LABELS[k]}</b>`)});return lines.join('')||'<span class="muted">No stat change</span>'}
function equipInventoryItem(itemId,heroId){const item=state.run.inventory.find(x=>x.id===itemId),hero=state.run.heroes.find(h=>h.id===heroId);if(!item||!hero||!canEquip(hero,item))return;const previousOwner=equippedOwner(item);if(previousOwner)Object.keys(previousOwner.gear).forEach(slot=>{if(previousOwner.gear[slot]?.id===item.id)previousOwner.gear[slot]=null});const oldNatural=naturalMaxHp(hero),oldStats=gearStats(hero),hpRatio=hero.hp/hero.maxHp,manaRatio=hero.maxMana?hero.mana/hero.maxMana:1;hero.gear[item.slot]=item;const nextStats=gearStats(hero);hero.maxHp=Math.max(1,hero.maxHp+naturalMaxHp(hero)-oldNatural);hero.hp=Math.max(1,hero.maxHp*hpRatio);hero.maxMana=Math.max(0,hero.maxMana+nextStats.mana-oldStats.mana);hero.mana=hero.maxMana*manaRatio;closeOverlay();save();toast(`${hero.name} equipped ${item.name}.`);render()}
function equipBest(item){state.run.inventory=state.run.inventory||[];state.run.inventory.push(item);toast(`${item.name} added to the run inventory.`)}
function advanceNode(){const r=state.run;delete r.lockedNodeType;r.step++;r.mode='map';save();render()}
function renderRecruit(){const r=state.run;return `<section class="panel"><div class="screenTitle"><h2>A Survivor Joins the Road</h2><p class="muted">Inspect the candidates and recruit one before entering ${REGIONS[r.region+1].name}.</p></div><div class="heroGrid">${r.recruitChoices.map((h,i)=>`<div class="choice recruitChoice">${heroCard(h)}<button class="btn gold" onclick="takeRecruit(${i})">Recruit ${h.class}</button></div>`).join('')}</div></section>`}
function takeRecruit(i){const r=state.run,h=r.recruitChoices[i],hpBonus=r.perks.filter(p=>p.type==='hp').reduce((a,p)=>a+p.value,0);if(hpBonus){h.maxHp=Math.round(h.maxHp*(1+hpBonus));h.hp=h.maxHp}r.heroes.push(h);r.region++;r.step=0;r.nodes=makeRegionMap();r.mode='map';delete r.recruitChoices;r.heroes.forEach(hero=>hero.hp=Math.max(1,Math.min(hero.maxHp,hero.hp+hero.maxHp*.35)));save();render()}
function abilityShrine(){const heroes=state.run.heroes.filter(h=>h.hp>0&&(h.augments||[]).length<3);if(!heroes.length){toast('The shrine has nothing left to teach this party.');return advanceNode()}showOverlay('Shrine of Mastery',`<p class="muted">Choose an adventurer whose class ability will be transformed for this run.</p><div class="equipGrid">${heroes.map(h=>`<button class="choice equipChoice" onclick="chooseAbilityAugment(${h.id})">${img('classes/'+CLASSES[h.class].icon)}<strong>${h.name}</strong><div class="muted">${h.class} · ${ABILITIES[h.class].name}</div><div class="itemStats">${(h.augments||[]).map(id=>`<span>${ABILITY_AUGMENTS[h.class].find(x=>x[0]===id)?.[1]||id}</span>`).join('')||'<span>No augments yet</span>'}</div></button>`).join('')}</div>`)}
function chooseAbilityAugment(heroId){const h=findHero(heroId),choices=ABILITY_AUGMENTS[h.class].filter(x=>!h.augments.includes(x[0]));if(!choices.length)return;closeOverlay();showOverlay('Empower '+ABILITIES[h.class].name,`<p class="muted">Choose one permanent ability change for ${h.name} this run.</p><div class="choiceGrid">${choices.map(a=>`<button class="choice" onclick="takeAbilityAugment(${h.id},'${a[0]}')"><strong>${a[1]}</strong><div class="muted">${a[2]}</div></button>`).join('')}</div>`)}
function takeAbilityAugment(heroId,id){const h=findHero(heroId),def=ABILITY_AUGMENTS[h.class].find(x=>x[0]===id);if(!def||h.augments.includes(id))return;h.augments.push(id);closeOverlay();toast(`${h.name} learned ${def[1]}.`);advanceNode()}
function relicVault(){state.run.relics=state.run.relics||[];const choices=RELICS.filter(x=>!state.run.relics.includes(x[0])).sort(()=>Math.random()-.5).slice(0,3);if(!choices.length){toast('The relic vault is empty.');return advanceNode()}showOverlay('Relic Vault',`<p class="muted">Choose one relic. Its rule affects the entire party for the rest of this run.</p><div class="choiceGrid">${choices.map(r=>`<button class="choice" onclick="takeRelic('${r[0]}')"><span class="big">⬡</span><strong>${r[1]}</strong><div class="muted">${r[2]}</div></button>`).join('')}</div>`)}
function takeRelic(id){const relic=RELICS.find(x=>x[0]===id);if(!relic||state.run.relics.includes(id))return;state.run.relics.push(id);closeOverlay();toast(`${relic[1]} joined the party relics.`);advanceNode()}
function treasureEvent(){const item=makeCanonicalItem(),gold=30+state.run.region*25;showOverlay('An Abandoned Cache',`<p class="muted">The party can only carry one prize safely.</p><div class="choiceGrid"><button class="choice" onclick="eventItem(${JSON.stringify(item).replace(/"/g,'&quot;')})"><strong>${item.name}</strong><div class="muted">Tier ${item.tier} · ${item.rarity} ${item.slot}</div></button><button class="choice" onclick="eventGold(${gold})"><strong>${gold} Gold</strong><div class="muted">Add it to the run purse.</div></button></div>`)}
function eventItem(item){equipBest(item);closeOverlay();advanceNode()}function eventGold(n){state.run.gold+=n;closeOverlay();advanceNode()}
function storyEvent(){const h=pick(state.run.heroes),events=[{title:'A Broken Oath',text:`${h.name} finds the banner of a failed expedition.`,choices:[['Honor the fallen','Party gains 10% maximum HP','oathHp'],['Strip it for valuables','Gain 55 Run Gold','gold55']]},{title:'The Narrow Bridge',text:'Something follows beneath the bridge.',choices:[['Cross carefully','Heal the most wounded hero','healWounded'],['Set an ambush','Gain 12% party attack','ambush']]},{title:'A Familiar Voice',text:`${h.name} hears someone calling from the dark.`,choices:[['Follow the voice','Gain a usable random item','randomGear'],['Keep moving','Gain 40 Run Gold','gold40']]}],e=pick(events);showOverlay(e.title,`<p>${e.text}</p><div class="choiceGrid">${e.choices.map(([name,desc,effect])=>`<button class="choice" onclick="resolveStory('${effect}')"><strong>${name}</strong><div class="muted">${desc}</div></button>`).join('')}</div>`)}
function resolveStory(effect){const r=state.run;if(effect==='oathHp'){r.perks.push({name:'Oathbound',desc:'Party maximum HP +10%.',type:'hp',value:.1});r.heroes.forEach(h=>{h.maxHp=Math.round(h.maxHp*1.1);h.hp=Math.min(h.maxHp,h.hp+h.maxHp*.2)})}else if(effect==='gold55')r.gold+=55;else if(effect==='healWounded'){const h=[...r.heroes].sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];h.hp=Math.min(h.maxHp,h.hp+h.maxHp*.5);toast(`${h.name} recovered 50% health.`)}else if(effect==='ambush')r.perks.push({name:'Ambush Training',desc:'Party attack +12%.',type:'attack',value:.12});else if(effect==='randomGear'){const item=makeCanonicalItem();r.inventory=r.inventory||[];r.inventory.push(item);toast(`${item.name} added to the run inventory.`)}else if(effect==='gold40')r.gold+=40;closeOverlay();advanceNode()}
function merchantEvent(){const r=state.run;if(!r.merchantStock){const gear=Array.from({length:6},(_,index)=>{const item=makeCanonicalItem(rollShopRarity(index===0)),cost=shopItemCost(item);return{kind:'gear',item,cost}}),consumables=Object.entries(CONSUMABLES).map(([id,c])=>({kind:'consumable',id,cost:c.cost+r.region*6}));r.merchantStock=[...gear,...consumables]}showOverlay('The Road Trader',`<p class="muted">Every trader carries at least one Epic-or-better item. Prices rise sharply with rarity and tier.</p><p class="muted">Buy as many items as you can afford. The trader leaves only when you choose Leave.</p><div class="choiceGrid traderStock">${r.merchantStock.map((stock,index)=>stock.kind==='gear'?`<button class="choice traderItem" ${r.gold<stock.cost?'disabled':''} onclick="buyMerchantStock(${index})"><span class="traderPrice">${stock.cost}g</span>${itemArt(stock.item)}<strong class="rarity-${stock.item.rarity}">${stock.item.name}</strong><div class="muted">Tier ${stock.item.tier} · ${stock.item.rarity}</div><div class="itemStats">${itemStatLines(stock.item).map(s=>`<span>${s}</span>`).join('')}</div><span class="choiceHint">Buy equipment →</span></button>`:`<button class="choice traderItem consumableShopItem" ${r.gold<stock.cost?'disabled':''} onclick="buyMerchantStock(${index})"><span class="traderPrice">${stock.cost}g</span><span class="consumableIcon">${CONSUMABLES[stock.id].icon}</span><strong>${CONSUMABLES[stock.id].name}</strong><div class="muted">${CONSUMABLES[stock.id].desc}</div><span class="choiceHint">Buy consumable →</span></button>`).join('')}</div><div class="actions"><button class="btn primary" onclick="leaveMerchant()">Leave Trader</button></div>`)}
function buyMerchantStock(index){const r=state.run,stock=r.merchantStock?.[index];if(!stock||r.gold<stock.cost)return;r.gold-=stock.cost;if(stock.kind==='gear'){r.inventory=r.inventory||[];r.inventory.push(stock.item);toast(`${stock.item.name} added to inventory.`)}else{r.consumables=r.consumables||{};r.consumables[stock.id]=(r.consumables[stock.id]||0)+1;toast(`${CONSUMABLES[stock.id].name} added to inventory.`)}r.merchantStock.splice(index,1);save();merchantEvent()}
function leaveMerchant(){delete state.run.merchantStock;closeOverlay();advanceNode()}
function showOverlay(title,body){closeOverlay();document.body.insertAdjacentHTML('beforeend',`<div class="overlay" id="overlay" onclick="if(event.target===this)closeOverlay()"><section class="panel modal"><h2>${title}</h2>${body}</section></div>`)}function closeOverlay(){$('#overlay')?.remove()}
function confirmAbandon(){const gems=Math.floor(state.run.encounters/2);showOverlay('Abandon this expedition?',`<p>The party will disband and all unspent Run Gold will be lost.</p><p class="muted">Progress reward: ${gems} Gems.</p><div class="actions"><button class="btn" onclick="closeOverlay()">Continue Run</button><button class="btn danger" onclick="closeOverlay();endRun(false)">Abandon Expedition</button></div>`)}
function endRun(won){clearInterval(battleTimer);battleTimer=null;cancelAnimationFrame(battleFrame);battleFrame=null;const r=state.run,gems=won?40+r.encounters*3:Math.floor(r.encounters/2),names=r.heroes.map(h=>h.name);state.gems+=gems;state.history.push({won,party:names,region:REGIONS[Math.min(r.region,3)].name,battles:r.encounters,gems,date:Date.now()});if(state.history.length>30)state.history.shift();state.run=null;save();$('#app').innerHTML=`<div class="shell">${header()}<section class="panel banner"><h2>${won?'Expedition Conquered':'The Expedition Is Lost'}</h2><p>${won?`${names.join(', ')} retire as legends.`:`${names.join(', ')} will not return to the road.`}</p><p class="muted">${gems} Gems were earned from expedition progress. Unspent Run Gold was left behind.</p><button class="btn primary" onclick="render()">Return to Guild</button></section></div>`}

// Turn-based combat. Initiative establishes a fresh order at the start of every round.
function heroInitiative(h){const gs=gearStats(h),dex=characterCoreStat(h,'dex'),haste=1+runBoonTotal('speed');return Math.max(1,Math.round(((CLASSES[h.class].initiative||8)+dex*.12)*(1+gs.attackSpeed/100)*haste*10)/10)}
function unitInitiative(u){return u.class?heroInitiative(u):Math.max(1,(u.initiative||8)+(u.initiativePenalty||0))}
function turnUnit(id){const r=state.run;return r?.heroes.find(x=>x.id===id)||r?.battle?.enemies.find(x=>x.id===id)}
function livingHeroes(){return state.run.heroes.filter(h=>h.hp>0)}
function livingEnemies(){return state.run.battle.enemies.filter(e=>e.hp>0)}
function buildTurnOrder(){const b=state.run.battle,units=[...livingHeroes(),...livingEnemies()];b.turnOrder=units.sort((a,c)=>unitInitiative(c)-unitInitiative(a)||Math.random()-.5).map(x=>x.id);b.turnIndex=0;b.round=(b.round||0)+1;if(b.round>1){livingHeroes().forEach(h=>{const gs=gearStats(h);h.mana=Math.min(h.maxMana,h.mana+h.manaRegen+gs.manaRegen);if(gs.regen>0)applyHealing(h,h,gs.regen);if(h.regenRounds>0){applyHealing(h,h,h.maxHp*.08);h.regenRounds--}if(h.sanctuaryRounds>0)h.sanctuaryRounds--;if(h.tauntRounds>0)h.tauntRounds--});livingEnemies().forEach(e=>{if(e.initiativePenaltyRounds>0&&!--e.initiativePenaltyRounds)e.initiativePenalty=0});if(b.lifestealRounds>0)b.lifestealRounds--;b.log.unshift(`Round ${b.round}: the party regenerates Mana.`)}save()}
function beginCombat(type){const r=state.run,reg=REGIONS[r.region];if(r.enemyLevelBase==null)r.enemyLevelBase=r.region>0?1+(r.region-1)*5+12:0;const level=r.enemyLevelBase+r.step+1,boss=type==='boss',elite=type==='elite',count=boss?1:Math.min(4,2+Math.floor(r.region/2)+(elite?1:0));const enemies=Array.from({length:count},()=>{const data=boss?reg.boss:pick(reg.enemies),e=enemyUnit(data[0],data[1],level,elite,boss);e.initiative=(boss?11:elite?10:8)+Math.min(5,level*.12);e.statuses={};return e});r.heroes.forEach(h=>{ensureHeroResources(h);h.turnCooldowns={};h.damage=0;h.damageTaken=0;h.healing=0;h.guardTurns=0;h.sanctuaryRounds=hasRelic('guardianBell')?2:0;h.tauntRounds=0});assignPartyFormation(r.heroes);r.battle={id:uid(),type,enemies,round:0,turnOrder:[],turnIndex:0,activeUnitId:null,pendingAction:null,phoenixUsed:false,log:[`${boss?'Boss battle':'Battle'} begins. Highest Initiative acts first.`]};r.mode='combat';buildTurnOrder();save();render()}
function startBattleLoop(){const b=state.run?.battle;if(!b||b.turnLocked)return;if(b.resolved){setTimeout(()=>completeBattleVictory(b.id),Math.max(0,2000-(Date.now()-(b.victoryAt||Date.now()))));return}if(!Array.isArray(b.turnOrder)){b.round=0;b.turnOrder=[];b.turnIndex=0;b.activeUnitId=null;b.pendingAction=null;state.run.heroes.forEach(h=>{h.turnCooldowns={}});buildTurnOrder()}if(b.activeUnitId){const actor=turnUnit(b.activeUnitId);if(actor&&!actor.class&&b.enemyScheduledFor!==actor.id){b.enemyScheduledFor=actor.id;setTimeout(()=>enemyTurn(actor.id),550)}return}continueTurnBattle()}
function continueTurnBattle(){const r=state.run,b=r?.battle;if(!b||r.mode!=='combat'||b.resolved)return;if(!livingHeroes().length)return endRun(false);if(!livingEnemies().length)return winBattle();while(b.turnIndex>=b.turnOrder.length)buildTurnOrder();let actor=turnUnit(b.turnOrder[b.turnIndex]);while((!actor||actor.hp<=0)&&b.turnIndex<b.turnOrder.length){b.turnIndex++;actor=turnUnit(b.turnOrder[b.turnIndex])}if(!actor){buildTurnOrder();return continueTurnBattle()}b.activeUnitId=actor.id;b.pendingAction=null;if(actor.statuses?.poison){const poison=actor.statuses.poison,damage=Math.min(actor.hp,poison.damage);actor.hp-=damage;const source=r.heroes.find(h=>h.id===poison.sourceId);if(source)source.damage+=damage;b.log.unshift(`${actor.name} suffers ${damage} poison damage.`);if(!--poison.turns)delete actor.statuses.poison;if(actor.hp<=0){save();return finishTurn(actor)}}if(actor.skipTurns>0){actor.skipTurns--;b.turnLocked=true;b.log.unshift(`${actor.name} loses the turn.`);save();render();return setTimeout(()=>finishTurn(actor),450)}save();render()}
function finishTurn(actor,usedAbility=null){if(actor?.class){actor.turnCooldowns=actor.turnCooldowns||{};Object.keys(actor.turnCooldowns).forEach(key=>{if(key!==usedAbility)actor.turnCooldowns[key]=Math.max(0,actor.turnCooldowns[key]-1)});if(actor.guardTurns>0)actor.guardTurns--}const b=state.run?.battle;if(!b)return;b.turnIndex++;b.activeUnitId=null;b.enemyScheduledFor=null;b.pendingAction=null;b.turnLocked=false;processRelicEffects();save();if(!livingHeroes().length)return endRun(false);if(!livingEnemies().length)return winBattle();setTimeout(continueTurnBattle,180)}
function turnDamage(source,target,mult=1){const gs=gearStats(source),crit=Math.random()<heroSheetStats(source).crit,variance=.12+(gs.damageVariance||0),raw=Math.round(effectiveAtk(source)*mult*(crit?1.75+gs.critDamage:1)*(1-variance+Math.random()*variance*2)),damage=Math.max(1,raw);target.hp=Math.max(0,target.hp-damage);source.damage+=damage;if(target.hp<=0)source.kills++;const lifesteal=(gs.lifesteal+(state.run.battle.lifestealRounds>0?12:0))/100;if(lifesteal)applyHealing(source,source,damage*lifesteal);return{damage,crit}}
function chooseTurnAction(action){const b=state.run?.battle,actor=turnUnit(b?.activeUnitId);if(!b||!actor?.class||b.resolved)return;if(action==='defend'){actor.guardTurns=2;actor.tauntRounds=['Warrior','Paladin'].includes(actor.class)?2:actor.tauntRounds;b.log.unshift(`${actor.name} defends and braces for the next attack.`);return finishTurn(actor)}const ability=action==='basic'?null:TURN_ABILITIES[actor.class].find(a=>a.key===action);if(ability&&((actor.turnCooldowns?.[ability.key]||0)>0||actor.mana<turnAbilityCost(actor,ability)))return;if(action==='consumable'){b.pendingAction='consumable';save();return render()}if(action==='basic'||ability?.target==='enemy'||ability?.target==='ally'){b.pendingAction=action;save();return render()}executeHeroAction(actor,action,null)}
function turnAbilityCost(h,a){return Math.round(a.cost*(a.key==='primary'&&hasAugment(h,'efficient')?.7:1))}
function chooseTurnTarget(id){const b=state.run?.battle,actor=turnUnit(b?.activeUnitId);if(!actor?.class||!b.pendingAction)return;executeHeroAction(actor,b.pendingAction,turnUnit(id))}
function executeHeroAction(h,action,target){const r=state.run,b=r.battle,allies=livingHeroes(),enemies=livingEnemies(),ability=TURN_ABILITIES[h.class].find(a=>a.key===action);if(action==='basic'){const hit=turnDamage(h,target,1);b.log.unshift(`${h.name} attacks ${target.name} for ${hit.damage}${hit.crit?' critical':''}.`);return finishTurn(h)}if(!ability)return;if(h.mana<turnAbilityCost(h,ability)||(h.turnCooldowns?.[ability.key]||0)>0)return;h.mana-=turnAbilityCost(h,ability);h.turnCooldowns[ability.key]=Math.max(1,ability.cooldown-(hasAugment(h,'tempo')||hasRelic('hourglass')?1:0));let text='';if(h.class==='Warrior'&&action==='primary'){let total=0;enemies.forEach(e=>total+=turnDamage(h,e,1.05).damage);text=`${h.name} cleaves the enemy line for ${total} damage.`}else if(h.class==='Warrior'){const hit=turnDamage(h,target,.85);target.skipTurns=(target.skipTurns||0)+1;text=`${h.name} shield-bashes ${target.name} for ${hit.damage} and stuns it.`}else if(h.class==='Paladin'&&action==='primary'){const ally=target||[...allies].sort((a,c)=>a.hp/a.maxHp-c.hp/c.maxHp)[0],amount=applyHealing(h,ally,effectiveAtk(h)*1.6);text=`${h.name} restores ${Math.round(amount)} health to ${ally.name}.`}else if(h.class==='Paladin'){const hit=turnDamage(h,target,1.5),ally=[...allies].sort((a,c)=>a.hp/a.maxHp-c.hp/c.maxHp)[0];applyHealing(h,ally,hit.damage*.3);text=`${h.name} smites ${target.name} for ${hit.damage} and shares the radiance.`}else if(h.class==='Rogue'&&action==='primary'){const hit=turnDamage(h,target,2.15);text=`${h.name} backstabs ${target.name} for ${hit.damage}.`}else if(h.class==='Rogue'){const hit=turnDamage(h,target,1.2);target.statuses.poison={turns:3,damage:Math.max(2,Math.round(hit.damage*.18)),sourceId:h.id};text=`${h.name} poisons ${target.name} for ${hit.damage} damage.`}else if(h.class==='Ranger'&&action==='primary'){let total=0;enemies.forEach(e=>total+=turnDamage(h,e,.9).damage);text=`${h.name}'s volley deals ${total} damage.`}else if(h.class==='Ranger'){const hit=turnDamage(h,target,1.35);target.initiativePenalty=-5;target.initiativePenaltyRounds=2;text=`${h.name} pins ${target.name} for ${hit.damage}, reducing Initiative.`}else if(h.class==='Mage'&&action==='primary'){const hit=turnDamage(h,target,2.1);target.statuses.poison={turns:2,damage:Math.max(2,Math.round(hit.damage*.16)),sourceId:h.id};text=`${h.name}'s Fireball hits ${target.name} for ${hit.damage} and burns it.`}else if(h.class==='Mage'){let total=0;enemies.forEach(e=>{total+=turnDamage(h,e,.8).damage;e.skipTurns=(e.skipTurns||0)+1});text=`${h.name}'s Frost Nova deals ${total} and freezes the enemy line.`}else if(h.class==='Priest'&&action==='primary'){const ally=target||[...allies].sort((a,c)=>a.hp/a.maxHp-c.hp/c.maxHp)[0],amount=applyHealing(h,ally,effectiveAtk(h)*1.9);text=`${h.name} mends ${ally.name} for ${Math.round(amount)}.`}else{let total=0;allies.forEach(a=>{total+=applyHealing(h,a,effectiveAtk(h)*.65);a.sanctuaryRounds=2});text=`${h.name} invokes Sanctuary, restoring ${Math.round(total)} party health.`}b.log.unshift(text);if(hasRelic('echoStone')&&Math.random()<.25){h.turnCooldowns[ability.key]=0;b.log.unshift(`The Echo Stone immediately refreshes ${ability.name}.`)}return finishTurn(h,ability.key)}
function enemyTurn(id){const e=turnUnit(id),b=state.run?.battle;if(!e||e.hp<=0||b?.activeUnitId!==id)return continueTurnBattle();const heroes=livingHeroes(),taunter=heroes.find(h=>h.tauntRounds>0),target=taunter||enemyTarget(heroes),gs=gearStats(target);if(Math.random()<gs.parry){b.log.unshift(`${target.name} parries ${e.name}.`);return finishTurn(e)}let damage=Math.max(1,Math.round(e.atk*(.82+Math.random()*.3)*100/(100+gs.def*3)));if(target.guardTurns>0)damage=Math.round(damage*.55);if(target.sanctuaryRounds>0)damage=Math.round(damage*.7);if(hasRelic('ironIdol'))damage=Math.round(damage*.88);target.hp=Math.max(0,target.hp-damage);target.damageTaken+=damage;b.log.unshift(`${e.name} attacks ${target.name} for ${damage}.`);finishTurn(e)}
function initiativeTimeline(){const b=state.run.battle,remaining=(b.turnOrder||[]).slice(b.turnIndex).map(turnUnit).filter(u=>u&&u.hp>0);return `<div class="initiativeTrack">${remaining.map((u,i)=>`<div class="initiativeToken ${i===0?'active':''} ${u.class?'heroToken':'enemyToken'}">${u.name}<small>${unitInitiative(u)} Initiative</small></div>`).join('')}</div>`}
function turnActionPanel(){const b=state.run.battle,h=turnUnit(b.activeUnitId);if(!h?.class)return `<div class="turnPrompt enemyThinking">${h?`${h.name} is choosing an action…`:'Advancing turn…'}</div>`;if(b.pendingAction==='consumable'){const owned=Object.entries(state.run.consumables||{}).filter(([,n])=>n>0);return `<div class="turnPrompt"><h3>Choose a consumable</h3><div class="turnActions">${owned.map(([id,n])=>`<button class="turnAction" onclick="useConsumable('${id}')">${CONSUMABLES[id].icon} ${CONSUMABLES[id].name} ×${n}</button>`).join('')||'<span class="muted">No consumables available.</span>'}<button class="turnAction" onclick="cancelTurnChoice()">Back</button></div></div>`}if(b.pendingAction){const ability=TURN_ABILITIES[h.class].find(a=>a.key===b.pendingAction),targets=ability?.target==='ally'?livingHeroes():livingEnemies();return `<div class="turnPrompt"><h3>Choose a target for ${b.pendingAction==='basic'?'Basic Attack':ability?.name}</h3><div class="turnActions">${targets.map(e=>`<button class="turnAction targetAction" onclick="chooseTurnTarget(${e.id})">${e.name}<small>${Math.ceil(e.hp)}/${e.maxHp} HP</small></button>`).join('')}<button class="turnAction" onclick="cancelTurnChoice()">Back</button></div></div>`}const abilities=TURN_ABILITIES[h.class];return `<div class="turnPrompt"><h3>${h.name}'s turn</h3><p class="muted">Choose an action. Mana regenerates for the party at the start of each new round.</p><div class="turnActions"><button class="turnAction" onclick="chooseTurnAction('basic')"><b>Basic Attack</b><small>No Mana · No cooldown</small></button>${abilities.map(a=>{const cd=h.turnCooldowns?.[a.key]||0,cost=turnAbilityCost(h,a),disabled=cd>0||h.mana<cost;return `<button class="turnAction abilityAction" ${disabled?'disabled':''} onclick="chooseTurnAction('${a.key}')"><b>${a.name}</b><small>${cost} Mana · ${cd?cd+' turns remaining':a.cooldown+' turn cooldown'}</small><span>${a.desc}</span></button>`}).join('')}<button class="turnAction" onclick="chooseTurnAction('defend')"><b>Defend</b><small>45% less damage from the next attack</small></button><button class="turnAction" onclick="chooseTurnAction('consumable')"><b>Use Consumable</b><small>Uses this turn</small></button></div></div>`}
function cancelTurnChoice(){const b=state.run?.battle;if(!b)return;b.pendingAction=null;save();render()}
function unitCard(u,enemy=false){const hp=clamp(u.hp/u.maxHp*100,0,100),path=enemy?'enemies/'+u.icon:'classes/'+CLASSES[u.class].icon,active=state.run.battle.activeUnitId===u.id;if(enemy)return `<div class="unit enemy ${u.hp<=0?'dead':''} ${active?'activeTurn':''}" id="unit-${u.id}"><div class="unitName">Lv. ${u.level} · ${u.name}<small>${unitInitiative(u)} Initiative</small></div>${img(path)}<div class="meterLabel"><span>Health</span><span>${Math.max(0,Math.ceil(u.hp))}/${u.maxHp}</span></div><div class="bar"><i style="width:${hp}%"></i></div></div>`;return `<div class="unit ${u.hp<=0?'dead':''} ${active?'activeTurn':''}" id="unit-${u.id}"><div class="unitName">${u.name}<small>${u.class} · ${heroInitiative(u)} Initiative · ${heroThreat(u).toFixed(2)} Threat</small></div>${img(path)}<div class="meterLabel"><span>Health</span><span>${Math.max(0,Math.ceil(u.hp))}/${u.maxHp}</span></div><div class="bar"><i style="width:${hp}%"></i></div><div class="meterLabel"><span>Mana</span><span>${Math.floor(u.mana)}/${u.maxMana}</span></div><div class="bar mana"><i style="width:${clamp(u.mana/u.maxMana*100,0,100)}%"></i></div></div>`}
function renderCombat(){const r=state.run,b=r.battle,reg=REGIONS[r.region];r.heroes.forEach(ensureHeroResources);return `<section class="panel combatField turnBasedCombat" style="background-image:url('${ASSET}backgrounds/${reg.bg}')"><div class="regionHead"><div class="eyebrow">ROUND ${b.round} · ${b.type==='boss'?'REGION BOSS':b.type==='elite'?'ELITE BATTLE':'BATTLE'}</div><h2>${reg.name}</h2></div>${initiativeTimeline()}<div class="combatSides"><div class="combatSide">${r.heroes.map(h=>unitCard(h)).join('')}</div><div class="combatSide">${b.enemies.map(e=>unitCard(e,true)).join('')}</div></div>${turnActionPanel()}<div class="combatBottom"><div class="combatLog">${b.log.join('<br>')}</div><aside class="combatReport"><h3>Battle Report</h3>${combatReportRows()}</aside></div></section>`}
function inspectHero(id){const h=findHero(id);if(!h)return;const z=heroSheetStats(h),race=RACE_DATA[h.race]||{},sub=(SUBCLASS_DATA[h.class]||[]).find(x=>x.id===h.subclass),passive=CLASS_PASSIVES[h.class],abilities=TURN_ABILITIES[h.class];showOverlay(h.name,`<div class="characterInspect"><div class="characterIdentity">${img('classes/'+CLASSES[h.class].icon)}<div><h3>${h.name}</h3><div class="muted">${sub?.name||h.class} · ${h.race} · Level ${h.level} · <span class="rarity-${h.rarity}">${h.rarity}</span></div><div class="muted">${h.trait}</div></div></div><div class="statSheet">${[['HP',z.hp],['Mana',z.mana],['Mana Regen / Round',z.manaRegen],['Attack',effectiveAtk(h)],['Initiative',z.initiative.toFixed(1)],['Threat',z.threat.toFixed(2)],['STR',z.str],['DEX',z.dex],['INT',z.int],['DEF',z.def],['MDEF',z.mdef],['Block',z.block],['Crit',(z.crit*100).toFixed(1)+'%'],['HP Regen / Round',z.regen]].map(([k,v])=>`<div class="sheetStat"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div>${abilities.map((a,i)=>`<section class="inspectSection abilityInspect"><h3>${i?'Second Ability':'Class Ability'} · ${a.name}</h3><p>${a.desc}</p><div class="itemStats"><span>${turnAbilityCost(h,a)} Mana</span><span>${a.cooldown} Turn Cooldown</span></div></section>`).join('')}<section class="inspectSection"><h3>Class Passive · ${passive[0]}</h3><p class="muted">${passive[1]}</p></section><section class="inspectSection"><h3>Race Passive · ${race.passive||'Heritage'}</h3><p class="muted">${race.desc||'No racial modifier.'}</p></section>${sub?`<section class="inspectSection"><h3>Subclass · ${sub.name}</h3><p><b>Passive</b><br>${sub.passive}</p><p class="muted"><b>Active</b><br>${sub.active}</p></section>`:''}<section class="inspectSection"><h3>Equipment</h3><div class="inspectLoadout">${['Weapon','Armor','Accessory'].map(slot=>{const it=h.gear[slot];return `<button class="gearInspectCard" onclick="closeOverlay();inspectGear(${h.id},'${slot}')"><span>${slot}</span><strong>${it?.name||'Empty'}</strong><small>${it?itemStatLines(it).join(' · '):'Nothing equipped'}</small></button>`}).join('')}</div></section></div><div class="actions"><button class="btn" onclick="closeOverlay()">Close</button></div>`)}
function useConsumable(id){const r=state.run,b=r?.battle,c=CONSUMABLES[id],actor=turnUnit(b?.activeUnitId);r.consumables=r.consumables||{};if(r.mode!=='combat'||!actor?.class||!c||(r.consumables[id]||0)<=0)return;const preserved=hasRelic('alchemySatchel')&&Math.random()<.35;if(!preserved)r.consumables[id]--;const heroes=livingHeroes(),enemies=livingEnemies();if(id==='healingPotion'){const h=[...heroes].sort((a,c)=>a.hp/a.maxHp-c.hp/c.maxHp)[0];if(h)applyHealing(actor,h,h.maxHp*.45)}else if(id==='regenTonic')heroes.forEach(h=>h.regenRounds=3);else if(id==='vampireElixir')b.lifestealRounds=3;else if(id==='fireballScroll'){const damage=70+r.region*35;enemies.forEach(e=>e.hp=Math.max(0,e.hp-damage));actor.damage+=damage*enemies.length}else if(id==='frostScroll')enemies.forEach(e=>e.skipTurns=(e.skipTurns||0)+1);b.log.unshift(`${actor.name} uses ${c.name}${preserved?' without consuming it':''}.`);finishTurn(actor)}
async function init(){try{const [items,races,subclasses,recipes]=await Promise.all([fetch(ITEM_DATA_URL),fetch('../guildmaster/data/races.json'),fetch('../guildmaster/data/subclasses.json'),fetch('../guildmaster/data/recipes.json')]);if(!items.ok||!races.ok||!subclasses.ok||!recipes.ok)throw new Error('Shared Guildmaster data unavailable');[ITEM_DATA,RACE_DATA,SUBCLASS_DATA,RECIPE_DATA]=await Promise.all([items.json(),races.json(),subclasses.json(),recipes.json()])}catch(error){console.warn('Guildmaster shared data could not be loaded; fallback values will be used.',error)}render()}
init();
